{
 "mode": "filter",
 "query": "invoice retention purge",
 "include_invalidated": true
}

{
 "command": "git ls-files && cat README* 2>/dev/null | head -50",
 "description": "List repo files and README"
}

{
 "command": "cat migrations/*.sql && cat scripts/backfill_tax.py scripts/export.py docs/ops/backfills.md && grep -rn -i \"retention\\|purge\\|2555\\|3650\" --exclude-dir=.engramdb . ; cat src/billing/refunds.py | head -60; cat .engramdb/memories/use-structlog* .engramdb/memories/money-moving*",
 "description": "Read schema, scripts, and related docs"
}

{
 "command": "cat pyproject.toml tests/test_db.py docker-compose.yml; grep -rn \"finalized_at\\|psycopg\\|connect(\" src scripts tests | head -20",
 "description": "Check deps and DB connection patterns"
}

{
 "command": "python -m py_compile scripts/purge_invoices.py && env -u DATABASE_URL python scripts/purge_invoices.py && python scripts/purge_invoices.py --batch-size 2000; echo rc=$?",
 "description": "Compile and smoke-test without a database"
}
